"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5578],{25331:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WorkbenchConfig","desc":"Single tuning surface for the Workbench crafting station: interaction\\nconstants, output template folders, and the recipe table. Edit gameplay here,\\nnever in service/controller code. The GUI is fixed to two material rows\\n(Wood/Metal), so recipe `Cost` is limited to those two materials.\\n\\nStudio setup required:\\n  1. Tag the `ReplicatedStorage/PlaceableItems/Workbench` Model with\\n     CollectionService tag `Workbench` (shared with the Shredder, which lives on\\n     the same station); give it a BasePart named `CraftPromptPart` (anywhere under\\n     the Model) holding a `ProximityPrompt`, and set its PrimaryPart.\\n  2. Create `ServerStorage/WeaponTemplates` holding craftable weapon Tools\\n     (e.g. clones of `Pistol`, `SMG`) \u2014 separate from StarterPack.\\n  3. Each craftable placeable needs its `ReplicatedStorage/PlaceableTools/<Name>` Tool.\\n  4. Wood/Metal reuse `ReplicatedStorage/CraftingMaterials`.","source":{"line":20,"path":"src/ReplicatedStorage/SharedModules/Configs/WorkbenchConfig.luau"}}')}}]);